            public ToolBarButton Refresh { get; private set; }
            public ToolBarButton New { get; private set; }
            public ToolBarButton Delete { get; private set; }
            public ToolBarButton Filter { get; private set; }
            public ToolBarButton Adjust { get; private set; }
            public ToolBarButton Export { get; private set; }
            public ToolBarButton Upload { get; private set; }
            public ToolBarButton PageFirst { get; private set; }
            public ToolBarButton PagePrev { get; private set; }
            public ToolBarButton PageNext { get; private set; }
            public ToolBarButton PageLast { get; private set; }
                
                public PxToolBar(string tabId)
                {
                    LongRun = new ToolBarButton("css=qp-long-run", "LongRun panel", tabId, null);
                    LongRun_cancel = new ToolBarButton("css=qp-long-run .qp-lr-cancel", "LongRun Cancel", tabId, null);
                    Refresh = new ToolBarButton("GridList_grid_topBarrefresh", "Refresh", tabId, null);
                    New = new ToolBarButton("GridList_grid_topBarinsert", "Add Row", tabId, null);
                    Delete = new ToolBarButton("GridList_grid_topBardelete", "Delete Row", tabId, null);
                    Delete.ConfirmAction = Controls.Alert.Alert.AlertToException;
                    Filter = new ToolBarButton("GridList_grid_topBarfilter", "Filter Settings", tabId, null);
                    Adjust = new ToolBarButton("GridList_grid_topBaradjust", "Fit to Screen", tabId, null);
                    Export = new ToolBarButton("GridList_grid_topBarexportToExcel", "Export to Excel", tabId, null);
                    Upload = new ToolBarButton("GridList_grid_topBarimport", "Load Records from File", tabId, null);
                    PageFirst = new ToolBarButton("GridList_grid_pagerLfirst", "firstPage", tabId, null);
                    PagePrev = new ToolBarButton("GridList_grid_pagerLprev", "prevPage", tabId, null);
                    PageNext = new ToolBarButton("GridList_grid_pagerRnext", "nextPage", tabId, null);
                    PageLast = new ToolBarButton("GridList_grid_pagerRlast", "lastPage", tabId, null);
                }
            }
            
            public class c_grid_row : GridRow
            {
                
            public CheckBox Selected { get; private set; }
            public Input Id { get; private set; }
            public Input View { get; private set; }
                
                public c_grid_row(c_gridlist_gridgrid grid) : 
                        base(grid)
                {
                    Selected = new CheckBox("colSelected", "Included", grid.TabId, "Selected");
                    Id = new Input("colId", "Grid ID", grid.TabId, "Id");
                    View = new Input("colView", "Table ID", grid.TabId, "View");
                }
            }
            
            public class c_grid_header : GridHeader
            {
                
                public CheckBoxColumnFilter Selected { get; private set; }
                public InputColumnFilter Id { get; private set; }
                public InputColumnFilter View { get; private set; }
                
                public c_grid_header(c_gridlist_gridgrid grid) : 
                        base(grid)
                {
                    Selected = new CheckBoxColumnFilter(grid.Row.Selected);
                    Id = new InputColumnFilter(grid.Row.Id);
                    View = new InputColumnFilter(grid.Row.View);
                }
            }
        }
        
